const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '2/3' },
      { kind: 'text', payload: '① 1/2' },
      { kind: 'text', payload: '② 2/3' },
      { kind: 'text', payload: '从小到大：1/2 < 2/3' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = Math.round(H * 0.55);
    var x0 = Math.round(W * 0.12);
    var x1 = Math.round(W * 0.88);
    var unit = x1 - x0;
    var xHalf = x0 + unit * 0.5;
    var xTwoThirds = x0 + unit * (2 / 3);
    var tickTop = 10;
    var tickBottom = 10;
    var axis = visualSdk.arrow(x0, y, x1, y, {});
    var tick0 = visualSdk.polyline([[x0, y - tickTop], [x0, y + tickBottom]]);
    var tick1 = visualSdk.polyline([[x1, y - tickTop], [x1, y + tickBottom]]);
    var tickHalf = visualSdk.polyline([[xHalf, y - tickTop], [xHalf, y + tickBottom]]);
    var tickTwoThirds = visualSdk.polyline([[xTwoThirds, y - tickTop], [xTwoThirds, y + tickBottom]]);
    var dotHalf = visualSdk.circle(xHalf, y, 5);
    var dotTwoThirds = visualSdk.circle(xTwoThirds, y, 5);
    var labelYAbove = y - 28;
    var labelYBelow = y + 30;
    return {
      schemaVersion: 1,
      sceneId: 'number-line-1-2-2-3',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axis },
        { id: 'tick0', commands: tick0 },
        { id: 'tick1', commands: tick1 },
        { id: 'tickHalf', commands: tickHalf },
        { id: 'tickTwoThirds', commands: tickTwoThirds },
        { id: 'dotHalf', commands: dotHalf },
        { id: 'dotTwoThirds', commands: dotTwoThirds }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axis', stroke: '#1f2937', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'tick0', stroke: '#1f2937', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'tick1', stroke: '#1f2937', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'tickHalf', stroke: '#1f2937', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'tickTwoThirds', stroke: '#1f2937', strokeWidth: 2, fill: 'none' },
          { type: 'path', pathId: 'dotHalf', stroke: '#dc2626', strokeWidth: 2, fill: '#dc2626' },
          { type: 'path', pathId: 'dotTwoThirds', stroke: '#2563eb', strokeWidth: 2, fill: '#2563eb' },
          { type: 'label', text: '0', x: x0, y: labelYBelow, fontSize: 16, textAnchor: 'middle', fill: '#111827' },
          { type: 'label', text: '1', x: x1, y: labelYBelow, fontSize: 16, textAnchor: 'middle', fill: '#111827' },
          { type: 'label', text: '① 1/2', x: xHalf, y: labelYAbove, fontSize: 16, textAnchor: 'middle', fill: '#dc2626' },
          { type: 'label', text: '② 2/3', x: xTwoThirds, y: labelYAbove, fontSize: 16, textAnchor: 'middle', fill: '#2563eb' },
          { type: 'label', text: '从小到大：1/2 < 2/3', x: W / 2, y: y + 64, fontSize: 16, textAnchor: 'middle', fill: '#111827' }
        ]
      }
    };
  }
};
